// =====================================================================
// WF2 - Clasificación y asignación de prioridad
// Entrada: tickets NUEVO (nodo "Leer tickets nuevos") y las categorías
//          activas con sus palabras clave (este nodo recibe categorías).
// Reglas:
//  1. Se normaliza el texto (minúsculas, sin tildes) para comparar.
//  2. Cada palabra clave encontrada suma 1 punto; si está en el asunto
//     suma 2, porque el asunto resume el problema.
//  3. Gana la categoría con más puntos. En empate gana la de menor id
//     (Red > Accesos > Hardware > Software). Sin coincidencias: "Otros".
//  4. Prioridad = prioridad base de la categoría, salvo que el texto
//     tenga una palabra de urgencia: entonces se eleva a ALTA.
// =====================================================================
const URGENCIA = ['urgente', 'urgencia', 'emergencia', 'no funciona', 'caido', 'caida',
                  'toda la oficina', 'servidor', 'inmediato', 'critico'];

function normalizar(texto) {
  return String(texto || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
function escapar(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function contiene(texto, palabra) {
  return new RegExp('(^|[^a-z0-9])' + escapar(palabra) + '($|[^a-z0-9])').test(texto);
}

const categorias = $input.all().map(i => i.json);
const otros = categorias.find(c => c.nombre === 'Otros');
const tickets = $('Leer tickets nuevos').all().map(i => i.json);

const resultado = [];

for (const t of tickets) {
  const asunto = normalizar(t.asunto);
  const descripcion = normalizar(t.descripcion);

  let mejor = null;
  for (const cat of categorias) {
    if (cat.nombre === 'Otros') continue;
    const palabras = [...new Set((cat.palabras_clave || []).map(normalizar))];
    let puntos = 0;
    const encontradas = [];
    for (const p of palabras) {
      const enAsunto = contiene(asunto, p);
      const enDesc = contiene(descripcion, p);
      if (enAsunto || enDesc) {
        puntos += enAsunto ? 2 : 1;
        encontradas.push(p);
      }
    }
    if (puntos > 0 && (!mejor || puntos > mejor.puntos ||
        (puntos === mejor.puntos && cat.id < mejor.cat.id))) {
      mejor = { cat, puntos, encontradas };
    }
  }

  const categoria = mejor ? mejor.cat : otros;
  const textoCompleto = asunto + ' ' + descripcion;
  const urgentes = URGENCIA.filter(u => contiene(textoCompleto, u));
  const prioridad = urgentes.length > 0 ? 'ALTA' : categoria.prioridad_base;

  let motivo = mejor
    ? `Categoría ${categoria.nombre} por: ${mejor.encontradas.join(', ')}`
    : 'Sin coincidencias: categoría Otros';
  motivo += urgentes.length > 0
    ? `. Prioridad ALTA por urgencia: ${urgentes.join(', ')}`
    : `. Prioridad base ${categoria.prioridad_base}`;

  resultado.push({
    json: {
      ticket_id: t.id,
      codigo: t.codigo,
      categoria_id: categoria.id,
      categoria: categoria.nombre,
      prioridad,
      motivo: motivo.slice(0, 300),
    },
  });
}

return resultado;
